    r0 = _buf_C2_RECV_MAIN_L;
    r1 = _blk_C2_RECV_MAIN_L;
    call _scope_tap;
#endif
#endif
#if DSP4_BLOCK_KERNELS
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = 0;
#endif
    call _scope_inject_blk;
#endif
#if (DSP4_NODE_LIMIT2 == 0 || 1 < DSP4_NODE_LIMIT2)
    call _C2_RECV_MAIN_R_process;
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
